<template><section class="pg5-inspector"><h3>Computed Style Inspector</h3><label>被测元素<select v-model="index" @change="measure"><option v-for="(node,i) in nodes" :key="i" :value="i">{{i}} · {{node.tagName.toLowerCase()}} {{node.getAttribute('aria-label')||node.className?.toString().slice(0,45)}}</option></select></label><Button size="sm" variant="text" @click="collect">重新测量</Button><dl><div v-for="(value,key) in actual" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd><small>Target {{target[key]??'无目标'}} · Difference {{difference(String(key),value)}} · {{compare(String(key),value)}}</small></div></dl><p>客观属性只认证此Story、元素和时间。视觉中心、完整键盘/对比度/读屏：NOT VERIFIED；Demo不认证生产。</p></section></template>
<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount,nextTick} from 'vue'
import Button from '@/components/ui/Button.vue'
import type {PlaygroundEntry} from './registry'
import type {MeasurementRecord} from './quality'
const props=withDefaults(defineProps<{host?:HTMLElement;entry:PlaygroundEntry;storyId?:string;size:string;revision:number;locateElement?:string}>(),{storyId:'basic'}),emit=defineEmits<{measurement:[records:MeasurementRecord[]]}>(),nodes=ref<HTMLElement[]>([]),index=ref(0),actual=ref<Record<string,string>>({})
function resolveToken(css:CSSStyleDeclaration,value:string):string{let out=value;for(let i=0;i<10&&out.startsWith('var(');i++){const name=out.slice(4,out.lastIndexOf(')')).split(',')[0]!.trim();const next=css.getPropertyValue(name).trim();if(!next)break;out=next}return out}
function normalizeValue(value:string):string{const hex=value.trim().match(/^#([0-9a-f]{6})$/i);if(hex){const n=parseInt(hex[1]!,16);return `rgb(${n>>16&255},${n>>8&255},${n&255})`}return value.replace(/\s+/g,'')}
const target=computed<Record<string,string|number>>(()=>{
 const node=nodes.value[Number(index.value)];if(!node)return {}
 const name=props.entry.name
 if(name==='Button'&&!node.matches('button.kb-button'))return {}
 if(name==='Input'&&!node.matches('input.kb-input'))return {}
 if(name==='Select'&&!node.matches('button.kb-select-trigger'))return {}
 if(name==='DatePicker'&&!node.matches('input'))return {}
 if(name==='Checkbox'&&!node.classList.contains('kb-checkbox-box'))return {}
 if(name==='TagsInput'&&!node.classList.contains('kf-tags-input'))return {}
 const raw:Record<string,string|number>={...props.entry.designSpecs}
 if(name==='Button'){const size=node.classList.contains('kb-button--sm')?'sm':node.classList.contains('kb-button--lg')?'lg':props.size;raw.height={sm:32,md:38,lg:44}[size as 'sm']||38}
 const css=getComputedStyle(node);const result=Object.fromEntries(Object.entries(raw).map(([key,value])=>[key,typeof value==='string'&&value.startsWith('var(')?resolveToken(css,value):value]));if(name==='Checkbox')result.labelGap=parseFloat(css.getPropertyValue('--kb-checkbox-gap'))||8;return result
})

let observer:ResizeObserver|undefined,mutation:MutationObserver|undefined,disposed=false
function identify(node:HTMLElement){return node.id?'#'+node.id:node.tagName.toLowerCase()+'.'+String(node.className||'').split(/\s+/).filter(Boolean).slice(0,2).join('.')+' [index='+index.value+']'}
function measure(){const node=nodes.value[Number(index.value)];if(!node||node.getBoundingClientRect().width===0){actual.value={};return}const r=node.getBoundingClientRect(),s=getComputedStyle(node);actual.value={width:r.width.toFixed(2)+'px',height:r.height.toFixed(2)+'px',fontSize:s.fontSize,fontWeight:s.fontWeight,lineHeight:s.lineHeight,padding:s.padding,margin:s.margin,gap:s.gap,border:s.border,borderWidth:s.borderWidth,borderStyle:s.borderStyle,borderRadius:s.borderRadius,outline:s.outline,outlineWidth:s.outlineWidth,outlineStyle:s.outlineStyle,boxShadow:s.boxShadow,minHeight:s.minHeight,color:s.color,backgroundColor:s.backgroundColor,focus:document.activeElement===node?'focused':'not focused'};if(props.entry.name==='Checkbox'&&node.classList.contains('kb-checkbox-box')){const text=node.closest('label')?.querySelector('.kb-checkbox-label');if(text)actual.value.labelGap=(text.getBoundingClientRect().left-r.right).toFixed(2)+'px'}const measuredAt=new Date().toISOString(),element=identify(node);emit('measurement',Object.entries(actual.value).map(([property,value])=>({componentId:props.entry.id,storyId:props.storyId,element,property,target:target.value[property]??'无目标',actual:value,status:compare(property,value),measuredAt,evidence:`getBoundingClientRect/getComputedStyle; viewport=${innerWidth}x${innerHeight}; theme=${document.documentElement.dataset.theme||'default'}`})))}
function collect(){if(disposed||!props.host)return;nodes.value=Array.from(props.host.querySelectorAll<HTMLElement>('.kf-tags-input,button,input,textarea,select,svg,.kb-checkbox-box,[role=tab],[role=switch]')).filter(n=>n.getBoundingClientRect().width>0).slice(0,100);if(index.value>=nodes.value.length)index.value=0;measure()}
function compare(key:string,value:string):'PASS'|'FAIL'|'NOT VERIFIED'{if(props.entry.implementationStatus!=='已接入真实组件'||target.value[key]===undefined)return 'NOT VERIFIED';if(props.entry.name==='Checkbox'&&!nodes.value[Number(index.value)]?.classList.contains('kb-checkbox-box'))return 'NOT VERIFIED';if(props.entry.name==='TagsInput'&&!nodes.value[Number(index.value)]?.classList.contains('kf-tags-input'))return 'NOT VERIFIED';const expected=target.value[key];if(typeof expected==='number')return Math.abs(parseFloat(value)-expected)<.5?'PASS':'FAIL';return normalizeValue(value)===normalizeValue(String(expected))?'PASS':'FAIL'}
function difference(key:string,value:string){const expected=target.value[key];if(expected===undefined)return '—';if(typeof expected==='number')return (parseFloat(value)-expected).toFixed(2)+'px';return normalizeValue(value)===normalizeValue(String(expected))?'相同':'不同'}
watch(()=>[props.host,props.entry.id,props.storyId],async()=>{observer?.disconnect();mutation?.disconnect();index.value=0;await nextTick();if(disposed)return;if(props.host){observer=new ResizeObserver(collect);observer.observe(props.host);mutation=new MutationObserver(collect);mutation.observe(props.host,{childList:true,subtree:true})}collect()},{immediate:true})
watch(()=>[props.size,props.revision],()=>void nextTick(collect))
watch(()=>props.locateElement,value=>{if(!value)return;const match=value.match(/\[index=(\d+)\]/);if(match)index.value=Number(match[1]);else{const i=nodes.value.findIndex(n=>n.id&&'#'+n.id===value);if(i>=0)index.value=i}measure()})
onBeforeUnmount(()=>{disposed=true;observer?.disconnect();mutation?.disconnect()})
</script>
<style scoped>.pg5-inspector{display:grid;gap:var(--kb-space-3);min-width:0}.pg5-inspector h3{font-size:var(--kb-fs-body-md);font-weight:var(--kb-fw-label)}.pg5-inspector select{width:100%;min-width:0;background:var(--kb-muted);border:0;border-radius:var(--kb-radius-sm);padding:var(--kb-space-2)}.pg5-inspector dl{display:grid;gap:var(--kb-space-2)}.pg5-inspector dl>div{padding-block:var(--kb-space-2);border-bottom:1px solid var(--kb-border)}.pg5-inspector dt{font-weight:var(--kb-fw-label)}.pg5-inspector dd{font-family:var(--font-mono);overflow-wrap:anywhere}.pg5-inspector small{font-size:var(--kb-fs-caption);color:var(--kb-muted-foreground)}</style>
